-- Reference schema. The Flask SQLAlchemy models create these tables automatically.
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at DATETIME NOT NULL);
CREATE TABLE categories (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, name VARCHAR(60) NOT NULL, kind ENUM('income','expense') NOT NULL, UNIQUE KEY uq_user_category(user_id,name,kind), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE transactions (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, category_id INT NOT NULL, kind ENUM('income','expense') NOT NULL, amount DECIMAL(12,2) NOT NULL, description VARCHAR(255), transaction_date DATE NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE budgets (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, category_id INT NOT NULL, month CHAR(7) NOT NULL, limit_amount DECIMAL(12,2) NOT NULL, UNIQUE KEY uq_user_budget_month(user_id,category_id,month), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE savings_goals (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, title VARCHAR(120) NOT NULL, target_amount DECIMAL(12,2) NOT NULL, saved_amount DECIMAL(12,2) NOT NULL DEFAULT 0, target_date DATE NULL, created_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
